import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {demo,parseCSV,localize,packetStats,grid} from './dataSource.js';
import './hardware.js';
import {summarize,fresnelRadius,signalRGB} from './analysis.js';
import {updateAnalysis,analysisConfig} from './analysis-ui.js';
import {createSceneLayers} from './sceneLayers.js';
const $=id=>document.getElementById(id),host=$('canvas');let rows=[],samples=[],vox=[],mesh,line,marker,playing=false,playMs=0,current=0,mode='',latestSnapshot=null,cameraFlight=null;
const layerControls=document.createElement('section');layerControls.className='section layersection';layerControls.innerHTML=`<h2>05 / SLICES & SCENE LAYERS</h2><div class="row"><label for="altfloor">Altitude floor</label><output id="floorout">All</output></div><input id="altfloor" type="range" min="0" max="8" value="0" step=".1"><div class="coords"><label>RSSI maximum<input id="maximum" type="number" value="0"></label><label>Beacon antenna altitude<input id="beaconalt" type="number" value="1.2" step=".1"></label></div><p class="hint">Antenna altitude uses the same reference as your CSV. Default 1.2 m is an assumption.</p><label class="check"><input id="fresnel" type="checkbox"> First Fresnel zone</label><div class="samplepicker"><label for="selectedsample">Sample</label><input id="selectedsample" type="number" min="1" value="1" step="1" aria-label="Selected drone sample"></div><div id="sampleinfo" class="sampleinfo">Load a survey to select a sample.</div><p id="fresnelinfo" class="hint">Select a sample or scrub the flight timeline.</p><label class="check"><input id="environment" type="checkbox"> Decorative warehouse</label><div class="coords"><label>Width · m<input id="roomwidth" type="number" min="2" max="150" value="22"></label><label>Depth · m<input id="roomdepth" type="number" min="2" max="150" value="17"></label><label>Height · m<input id="roomheight" type="number" min="2" max="150" value="10"></label></div><p class="hint">Room geometry is decorative; it does not model materials or change RF estimates.</p>`;document.querySelector('.workspace>aside').append(layerControls);

const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(44,1,.05,3000);const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.appendChild(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new THREE.AmbientLight(0xffffff,2));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(10,30,20);scene.add(sun);const ground=new THREE.GridHelper(60,60,0x3c526b,0x1d3044);scene.add(ground);const decor=new THREE.Group();scene.add(decor);const tripod=new THREE.Group();for(let i=0;i<3;i++){const a=i*Math.PI*2/3;const g=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(Math.cos(a)*.65,0,Math.sin(a)*.65),new THREE.Vector3(0,1.2,0)]);tripod.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:0xb6ed6b})));}tripod.add(new THREE.Mesh(new THREE.SphereGeometry(.18),new THREE.MeshBasicMaterial({color:0xb6ed6b})));tripod.children.at(-1).position.y=1.2;scene.add(tripod);const rings=[];for(let i=0;i<3;i++){let r=new THREE.Mesh(new THREE.RingGeometry(.98,1,80),new THREE.MeshBasicMaterial({color:0xb6ed6b,transparent:true,opacity:.3,side:THREE.DoubleSide}));r.rotation.x=-Math.PI/2;r.position.y=.02;scene.add(r);rings.push(r);}
function label(text,x,y,z,color='#8499ad'){const c=document.createElement('canvas');c.width=512;c.height=80;const ctx=c.getContext('2d');ctx.font='28px monospace';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(text,256,48);const texture=new THREE.CanvasTexture(c),s=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true}));s.position.set(x,y,z);s.scale.set(6,1,1);decor.add(s);}
function reset(){cameraFlight=null;let b= new THREE.Box3();for(const p of samples)b.expandByPoint(new THREE.Vector3(p.x,p.z,-p.y));if(b.isEmpty()){controls.target.set(10,3,-7);camera.position.set(33,25,30);}else{const c=b.getCenter(new THREE.Vector3()),size=b.getSize(new THREE.Vector3()),d=Math.max(8,size.length());controls.target.copy(c);camera.position.copy(c).add(new THREE.Vector3(d*.9,d*.65,d*.95));camera.far=Math.max(3000,d*8);camera.updateProjectionMatrix();}controls.update();}reset();
new ResizeObserver(()=>{const {width,height}=host.getBoundingClientRect();if(width<1||height<1)return;renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();}).observe(host);
function error(e){$('error').textContent=e.message||e;$('status').textContent='CHECK INPUT';}
function color(v){if(v.received===false)return new THREE.Color(0xd9414e);if($('metric').value==='SNR')return new THREE.Color().setHSL(Math.max(0,Math.min(1,(v.SNR_dB+15)/27))*.30,.65,.52);const rgb=signalRGB(v.RSSI_dBm,{strong:+$('strong').value,fading:+$('fading').value,dead:+$('dead').value});return new THREE.Color('rgb('+rgb.join(',')+')');}
function renderVox(){if(!mesh)return;const dummy=new THREE.Object3D();vox.forEach((v,i)=>{const visible=v.z<=+$('altitude').value&&v.z>=+$('altfloor').value&&v.RSSI_dBm>=+$('minimum').value&&v.RSSI_dBm<=+$('maximum').value&&(!$('weak').checked||v.RSSI_dBm<+$('fading').value);let s=+$('size').value*+$('resolution').value*(v.RSSI_dBm<+$('fading').value?1.35:1);dummy.position.set(v.x,v.z,-v.y);dummy.scale.setScalar(visible?s:0);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);mesh.setColorAt(i,color(v));});mesh.instanceMatrix.needsUpdate=true;if(mesh.instanceColor)mesh.instanceColor.needsUpdate=true;mesh.material.opacity=+$('opacity').value;line.visible=$('path').checked;$('floorout').textContent=(+$('altfloor').value).toFixed(1)+' m';$('altout').textContent=(+$('altitude').value).toFixed(1)+' m';$('sizeout').textContent=(+$('size').value).toFixed(2);$('opacityout').textContent=Math.round(+$('opacity').value*100)+'%';$('legendtitle').textContent=$('metric').value==='RSSI'?'RECEIVED SIGNAL STRENGTH · dBm':'SIGNAL TO NOISE RATIO · dB';$('ticks').innerHTML=($('metric').value==='RSSI'?[$('dead').value,$('fading').value,$('strong').value,'Strong']:['−15','−6','3','12']).map(x=>`<span>${x}</span>`).join('');}
const layers=createSceneLayers(THREE,scene);tripod.position.y=+$('beaconalt').value-1.2;
function dispose(obj){obj?.geometry?.dispose();obj?.material?.dispose();scene.remove(obj);}
async function rebuild(resetCamera=true){if(!rows.length)return;try{$('status').textContent='INTERPOLATING SURVEY…';await new Promise(requestAnimationFrame);let lat=+$('lat').value,lon=+$('lon').value;if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180)throw Error('Enter valid beacon coordinates.');if(!(+$('dead').value<+$('fading').value&&+$('fading').value<+$('strong').value))throw Error('Thresholds must satisfy: dead zone < fading < strong.');const next=localize(rows,lat,lon),g=grid(next,+$('resolution').value);samples=next;vox=g.vox;dispose(mesh);dispose(line);dispose(marker);for(const o of [...decor.children]){decor.remove(o);o.material?.map?.dispose();o.material?.dispose();o.geometry?.dispose();}mesh=new THREE.InstancedMesh(new THREE.SphereGeometry(.28,10,8),new THREE.MeshStandardMaterial({roughness:.7,transparent:true,opacity:.8}),vox.length);mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);scene.add(mesh);let pos=[],colors=[];for(const p of samples){pos.push(p.x,p.z,-p.y);let c=color(p);colors.push(c.r,c.g,c.b);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));line=new THREE.Line(geo,new THREE.LineBasicMaterial({vertexColors:true,transparent:true,opacity:.35}));scene.add(line);marker=new THREE.Mesh(new THREE.OctahedronGeometry(.5),new THREE.MeshBasicMaterial({color:0xe9ffff,wireframe:true}));scene.add(marker);const box=new THREE.Box3(new THREE.Vector3(g.min[0],g.min[2],-g.max[1]),new THREE.Vector3(g.max[0],g.max[2],-g.min[1]));decor.add(new THREE.Box3Helper(box,0x344b60));label('X / EAST (m)',(g.min[0]+g.max[0])/2,0,-g.min[1]+3);label('Y / NORTH (m)',g.max[0]+4,0,-(g.max[1]+g.min[1])/2);label('Z / ALTITUDE (m)',g.min[0]-4,g.max[2]+2,-g.max[1]);label('BEACON • 433 MHz',0,+$('beaconalt').value+1.3,0,'#b6ed6b');const timeouts=samples.filter(p=>p.received===false);if(timeouts.length){const o=new THREE.InstancedMesh(new THREE.OctahedronGeometry(.3),new THREE.MeshBasicMaterial({color:0xe64b60,wireframe:true}),timeouts.length),d=new THREE.Object3D();timeouts.forEach((p,i)=>{d.position.set(p.x,p.z,-p.y);d.updateMatrix();o.setMatrixAt(i,d.matrix);});decor.add(o);}const maxZ=g.max[2];$('altitude').min=g.min[2];$('altitude').max=maxZ;if(resetCamera)$('altitude').value=maxZ;else $('altitude').value=Math.min(maxZ,Math.max(g.min[2],+$('altitude').value));$('altfloor').min=g.min[2];$('altfloor').max=maxZ;if(resetCamera)$('altfloor').value=g.min[2];else $('altfloor').value=Math.min(maxZ,Math.max(g.min[2],+$('altfloor').value));$('samples').textContent=rows.length.toLocaleString();let values=rows.filter(r=>r.received!==false).map(r=>r.RSSI_dBm),mean=values.length?values.reduce((a,b)=>a+b,0)/values.length:null;$('mean').textContent=mean===null?'—':mean.toFixed(1);$('range').textContent=values.length?`${Math.min(...values).toFixed(0)} to ${Math.max(...values).toFixed(0)} dBm`:'No received packets';
const loss=packetStats(rows);$('loss').textContent=loss.percent===null?'—':loss.percent.toFixed(2);$('lost').textContent=`${loss.lost} missing · ${loss.resets} resets`;$('voxelcount').textContent=vox.length.toLocaleString();$('volume').textContent=`${$('resolution').value} m cells · local IDW`;$('duration').textContent=((rows.at(-1).Timestamp_ms-rows[0].Timestamp_ms)/1000).toFixed(1)+' seconds surveyed';$('bounds').textContent=`${(g.max[0]-g.min[0]).toFixed(1)} × ${(g.max[1]-g.min[1]).toFixed(1)} × ${(maxZ-g.min[2]).toFixed(1)} m / LOCAL CARTESIAN`;$('empty').classList.add('hidden');$('error').textContent='';$('status').textContent='SURVEY READY · HOVER TO INSPECT';$('source').textContent='● '+mode;if(resetCamera){playing=false;playMs=0;current=0;$('play').textContent='▶';}else current=Math.min(current,samples.length-1);$('timeline').max=rows.length-1;$('selectedsample').max=samples.length;latestSnapshot={name:$('filename').textContent,samples,voxels:vox,resolution:+$('resolution').value,thresholds:{strong:+$('strong').value,fading:+$('fading').value,dead:+$('dead').value},beacon:{latitude:lat,longitude:lon,altitudeM:+$('beaconalt').value},radio:analysisConfig(),demo:mode==='DEMO SURVEY'};latestSnapshot.summary=summarize(latestSnapshot);updateAnalysis(latestSnapshot);tripod.position.y=+$('beaconalt').value-1.2;renderVox();updateReplay();if(resetCamera)reset();}catch(e){error(e);}}
function load(data,name,isDemo=false){rows=data;mode=isDemo?'DEMO SURVEY':data[0].source==='payload-v2'?'PAYLOAD v2 · SIMULATED GPS':'CSV SURVEY';document.dispatchEvent(new CustomEvent('survey-loaded',{detail:{rows:data,name}}));$('lat').value=rows[0].Latitude;$('lon').value=rows[0].Longitude;$('filename').textContent=name;rebuild();}
$('demo').onclick=$('emptydemo').onclick=()=>load(demo(),'Synthetic warehouse · 20 × 15 × 8 m',true);
async function file(f){if(!f)return;try{if(f.size>15*1024*1024)throw Error('File exceeds 15 MB.');load(parseCSV(await f.text()),f.name);}catch(e){error(e);}}$('file').onchange=e=>file(e.target.files[0]);$('drop').onclick=()=>$('file').click();$('drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click();}};for(const type of ['dragover','dragleave','drop'])$('drop').addEventListener(type,e=>{e.preventDefault();$('drop').classList.toggle('over',type==='dragover');if(type==='drop')file(e.dataTransfer.files[0]);});
for(const id of ['altitude','altfloor','maximum','size','opacity','metric','path','weak','minimum'])$(id).addEventListener('input',renderVox);for(const id of ['strong','fading','dead'])$(id).onchange=()=>rebuild(false);$('resolution').onchange=()=>rebuild(false);$('origin').onclick=()=>rebuild();$('reset').onclick=reset;
const fmt=t=>`${Math.floor(t/60000).toString().padStart(2,'0')}:${Math.floor(t/1000%60).toString().padStart(2,'0')}`;
function updateReplay(){if(!samples.length)return;const p=samples[current];$('selectedsample').value=current+1;$('sampleinfo').textContent='#'+p.Packet_ID+' · X '+p.x.toFixed(1)+' / Y '+p.y.toFixed(1)+' / Z '+p.z.toFixed(1)+' m'+(p.received===false?' · no signal':' · RSSI '+p.RSSI_dBm.toFixed(1)+' dBm');layers.update(p,analysisConfig().frequencyMHz,fresnelRadius);marker.position.set(p.x,p.z,-p.y);$('timeline').value=current;$('time').textContent=fmt(p.Timestamp_ms-rows[0].Timestamp_ms)+' / '+fmt(rows.at(-1).Timestamp_ms-rows[0].Timestamp_ms);}
$('play').onclick=()=>{if(!rows.length)return;if(current===rows.length-1){current=0;playMs=0;}playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';};$('timeline').oninput=()=>{if(!rows.length)return;current=+$('timeline').value;playMs=rows[current].Timestamp_ms-rows[0].Timestamp_ms;updateReplay();};
const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();let hoverAt=0;renderer.domElement.addEventListener('pointermove',e=>{if(!mesh||performance.now()-hoverAt<75)return;hoverAt=performance.now();const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(mesh)[0];$('tooltip').style.display=hit?'block':'none';if(hit){let p=vox[hit.instanceId];$('tooltip').style.left=Math.min(e.clientX-r.left+12,r.width-250)+'px';$('tooltip').style.top=Math.min(e.clientY-r.top+12,r.height-145)+'px';$('tooltip').innerHTML=`INTERPOLATED VOXEL<br>X ${p.x.toFixed(1)} · Y ${p.y.toFixed(1)} · Z ${p.z.toFixed(1)} m<br>RSSI ${p.RSSI_dBm.toFixed(1)} dBm<br>SNR ${p.SNR_dB.toFixed(1)} dB<br>Nearest packet #${p.Packet_ID}`;}});renderer.domElement.onpointerleave=()=>$('tooltip').style.display='none';
function dialog(title,body){$('dialogtitle').textContent=title;$('dialogbody').innerHTML=body;$('dialog').showModal();}$('close').onclick=()=>$('dialog').close();
$('help').onclick=()=>dialog('Reading the RF volume','<p>Upload the original 7-column survey CSV, a 23-column payload v2 CSV, or an automatically saved project CSV. Payload timeout rows are excluded from RSSI averages and interpolation. BLE gaps are reported separately.</p><code>Timestamp_ms,Latitude,Longitude,Altitude_m,RSSI_dBm,SNR_dB,Packet_ID</code><p>Green is strong signal; yellow is fading; orange is weak multipath signal; red indicates the lowest received signal. Larger spheres emphasize weak measurements. Colors alone cannot identify the physical cause of loss.</p><p>Voxels use local inverse-distance interpolation from up to 12 nearby samples. Empty neighborhoods remain unfilled. Hover shows the nearest measured packet ID. Missing packet IDs are counted as gaps within one continuous survey; counter decreases start a new gap-count segment. Missing packets have no measured location and are not painted as known dead zones.</p><p>Coordinates use a local metric approximation. Z retains logged altitude; set the beacon antenna altitude in the same reference as your CSV. Demo uses a 433 MHz free-space loss baseline with synthetic attenuation blobs and noise.</p><p>A first Fresnel zone describes the clearance needed along a radio path: r = √(λd₁d₂/(d₁+d₂)), λ = c / 433 MHz. Obstructions inside it can weaken reception. Enable the Fresnel overlay and select a sample to inspect its first-zone radius. The decorative room is not a propagation simulation.</p>');
let prev=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min(100,now-prev);prev=now;if(playing&&rows.length){playMs+=dt*+$('speed').value;while(current<rows.length-1&&rows[current+1].Timestamp_ms-rows[0].Timestamp_ms<=playMs)current++;if(current===rows.length-1){playing=false;$('play').textContent='▶';}updateReplay();}rings.forEach((r,i)=>{let s=(now/1800+i/3)%1;r.scale.setScalar(.8+s*3);r.material.opacity=(1-s)*.22;});if(cameraFlight){const t=Math.min(1,(now-cameraFlight.start)/900),e=t*t*(3-2*t);controls.target.lerpVectors(cameraFlight.targetStart,cameraFlight.targetEnd,e);camera.position.lerpVectors(cameraFlight.cameraStart,cameraFlight.cameraEnd,e);if(t===1)cameraFlight=null;}controls.update();renderer.render(scene,camera);}requestAnimationFrame(animate);

let streamRows=[],streamDirty=false,streamBusy=false;document.addEventListener('payload-session',()=>{streamRows=[];streamDirty=false;});document.addEventListener('payload-row',e=>{streamRows.push(e.detail);if(streamRows.length>30000)streamRows.shift();streamDirty=true;});setInterval(async()=>{if(!streamDirty||streamBusy)return;streamBusy=true;streamDirty=false;const first=rows!==streamRows;rows=streamRows;mode='LIVE PAYLOAD · SIMULATED GPS';if(first){$('lat').value=rows[0].Latitude;$('lon').value=rows[0].Longitude;}$('filename').textContent='Live payload · latest 30,000 rows';document.dispatchEvent(new CustomEvent('survey-loaded',{detail:{rows,name:'Live payload'}}));try{await rebuild(first);}finally{streamBusy=false;}},2000);

$('selectedsample').onchange=()=>{if(!samples.length)return;current=Math.max(0,Math.min(samples.length-1,Math.round(+$('selectedsample').value)-1));playing=false;$('play').textContent='▶';playMs=rows[current].Timestamp_ms-rows[0].Timestamp_ms;updateReplay();};$('fresnel').onchange=updateReplay;$('beaconalt').onchange=()=>{if(!Number.isFinite(+$('beaconalt').value))$('beaconalt').value=1.2;rebuild(false);};document.addEventListener('radio-config',updateReplay);document.addEventListener('recompute-survey',()=>rebuild(false));
controls.addEventListener('start',()=>{cameraFlight=null;});document.addEventListener('focus-location',e=>{const p=e.detail,target=new THREE.Vector3(p.x,p.z,-p.y),distance=Math.max(5,p.extent*3);cameraFlight={start:performance.now(),targetStart:controls.target.clone(),targetEnd:target,cameraStart:camera.position.clone(),cameraEnd:target.clone().add(new THREE.Vector3(distance,distance*.65,distance))};});
document.addEventListener('export-map-png',()=>{if(!latestSnapshot){error('Load a survey before exporting a PNG.');return;}try{renderer.render(scene,camera);const c=document.createElement('canvas');c.width=renderer.domElement.width;c.height=renderer.domElement.height+110;const ctx=c.getContext('2d');ctx.fillStyle='#0b1420';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(renderer.domElement,0,60);ctx.fillStyle='#e3edf1';ctx.font='18px sans-serif';ctx.fillText('Airborne / 3D RF Spatial Mapper',20,28);ctx.font='11px monospace';ctx.fillStyle='#9fb5c6';ctx.fillText(latestSnapshot.name+' · '+(latestSnapshot.summary.simulated?'SIMULATED POSITIONS':'CSV POSITIONS')+' · X east / Y north / Z altitude (m)',20,47);const gradient=ctx.createLinearGradient(20,0,250,0);gradient.addColorStop(0,'#761b31');gradient.addColorStop(.33,'#f69b3d');gradient.addColorStop(.66,'#dde864');gradient.addColorStop(1,'#80d787');ctx.fillStyle=gradient;ctx.fillRect(20,c.height-34,230,7);ctx.fillStyle='#a6bccd';ctx.fillText($('metric').value==='RSSI'?'RSSI: '+$('dead').value+' / '+$('fading').value+' / '+$('strong').value+' dBm':'SNR: −15 to 12 dB',20,c.height-10);const a=document.createElement('a');a.download='rf-spatial-map.png';a.href=c.toDataURL('image/png');a.click();document.dispatchEvent(new CustomEvent('map-png-exported'));}catch(e){error('PNG export failed: '+e.message);}});
